"""Conway's Game of Life with every generation computed on the GPU via wgpu."""

import sys

import numpy as np
import wgpu

WORKGROUP = 8

SHADER = f"""
struct Dims {{
    width: u32,
    height: u32,
}};

@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size({WORKGROUP}, {WORKGROUP})
fn main(@builtin(global_invocation_id) gid: vec3<u32>) {{
    let x = gid.x;
    let y = gid.y;
    if (x >= dims.width || y >= dims.height) {{
        return;
    }}
    let w = i32(dims.width);
    let h = i32(dims.height);
    var n: u32 = 0u;
    for (var dy: i32 = -1; dy <= 1; dy = dy + 1) {{
        for (var dx: i32 = -1; dx <= 1; dx = dx + 1) {{
            if (dx == 0 && dy == 0) {{
                continue;
            }}
            let nx = i32(x) + dx;
            let ny = i32(y) + dy;
            if (nx >= 0 && nx < w && ny >= 0 && ny < h) {{
                n = n + src[u32(ny * w + nx)];
            }}
        }}
    }}
    let idx = y * dims.width + x;
    let alive = src[idx];
    var next: u32 = 0u;
    if (n == 3u || (alive == 1u && n == 2u)) {{
        next = 1u;
    }}
    dst[idx] = next;
}}
"""


def parse(text):
    tokens = text.split()
    if len(tokens) < 3:
        raise ValueError("missing header")
    width, height, generations = (int(t) for t in tokens[:3])
    if not (1 <= width <= 512 and 1 <= height <= 512 and 0 <= generations <= 1000):
        raise ValueError("header out of range")
    cells = tokens[3:]
    if len(cells) != width * height:
        raise ValueError(f"expected {width * height} cells, got {len(cells)}")
    if any(c not in ("0", "1") for c in cells):
        raise ValueError("cells must be 0 or 1")
    grid = np.array([int(c) for c in cells], dtype=np.uint32).reshape(height, width)
    return grid, generations


def step_gpu(grid, generations):
    height, width = grid.shape
    if generations == 0:
        return grid.copy()

    adapter = wgpu.gpu.request_adapter_sync(power_preference="high-performance")
    device = adapter.request_device_sync()

    size = grid.nbytes
    usage = (
        wgpu.BufferUsage.STORAGE
        | wgpu.BufferUsage.COPY_SRC
        | wgpu.BufferUsage.COPY_DST
    )
    buffers = [
        device.create_buffer_with_data(data=np.ascontiguousarray(grid), usage=usage),
        device.create_buffer(size=size, usage=usage),
    ]
    dims = device.create_buffer_with_data(
        data=np.array([width, height], dtype=np.uint32),
        usage=wgpu.BufferUsage.UNIFORM,
    )

    shader = device.create_shader_module(code=SHADER)
    layout = device.create_bind_group_layout(
        entries=[
            {
                "binding": 0,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.uniform},
            },
            {
                "binding": 1,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.read_only_storage},
            },
            {
                "binding": 2,
                "visibility": wgpu.ShaderStage.COMPUTE,
                "buffer": {"type": wgpu.BufferBindingType.storage},
            },
        ]
    )
    pipeline = device.create_compute_pipeline(
        layout=device.create_pipeline_layout(bind_group_layouts=[layout]),
        compute={"module": shader, "entry_point": "main"},
    )

    def bind_group(src, dst):
        return device.create_bind_group(
            layout=layout,
            entries=[
                {"binding": 0, "resource": {"buffer": dims, "offset": 0, "size": 8}},
                {"binding": 1, "resource": {"buffer": src, "offset": 0, "size": size}},
                {"binding": 2, "resource": {"buffer": dst, "offset": 0, "size": size}},
            ],
        )

    # Ping-pong: even generations read buffer 0 and write buffer 1, odd the reverse.
    groups = [bind_group(buffers[0], buffers[1]), bind_group(buffers[1], buffers[0])]
    gx = (width + WORKGROUP - 1) // WORKGROUP
    gy = (height + WORKGROUP - 1) // WORKGROUP

    encoder = device.create_command_encoder()
    for gen in range(generations):
        compute = encoder.begin_compute_pass()
        compute.set_pipeline(pipeline)
        compute.set_bind_group(0, groups[gen % 2])
        compute.dispatch_workgroups(gx, gy, 1)
        compute.end()
    device.queue.submit([encoder.finish()])

    result = buffers[generations % 2]
    data = device.queue.read_buffer(result)
    return np.frombuffer(data, dtype=np.uint32).reshape(height, width).copy()


def main(argv):
    if len(argv) < 2:
        print("usage: main.py <input-file>", file=sys.stderr)
        return 2
    with open(argv[1], encoding="utf-8") as f:
        grid, generations = parse(f.read())
    final = step_gpu(grid, generations)
    lines = [" ".join("1" if v else "0" for v in row) for row in final]
    lines.append(f"ALIVE {int(np.count_nonzero(final))}")
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

